			return ""
		}
		return t.Name
	case *ast.StarExpr:
		if t == nil {
			return ""
		}
		return baseTypeName(t.X)
	case *ast.IndexExpr:
		if t == nil {
			return ""
		}
		return baseTypeName(t.X)
	case *ast.IndexListExpr:
		if t == nil {
