func importAliases(files []*ast.File) map[string]string {
	aliases := make(map[string]string)
	for _, f := range files {
		if f == nil {
			continue
		}
		for _, imp := range f.Imports {
			if imp == nil || imp.Path == nil {
				continue
			}
			path, err := strconv.Unquote(imp.Path.Value)
			if err != nil || path == "" {
				continue
			}
			var name string
			if imp.Name != nil {
				name = imp.Name.Name
			}
			if name == "" {
				name = path
				if i := strings.LastIndex(path, "/"); i >= 0 {
					name = path[i+1:]
				}
			}
			if name == "_" || name == "." {
