	best, bestN := "", 0
	for _, m := range methods {

		if i := strings.Index(m.Sig, "("); i >= 0 {
			rest := m.Sig[i+1:]
			if j := strings.IndexAny(rest, " )"); j > 0 {
				name := rest[:j]
				counts[name]++
				if counts[name] > bestN {
					best, bestN = name, counts[name]
				}
			}
		}
	}
	if best == "" {
		best = "x"
	}
	return best
}
