	if err != nil {
		return ""
	}
	lines := strings.Split(string(data), "\n")
	start := fn.Line - 1
	if start < 0 || start >= len(lines) {
		return ""
	}
	end := fn.EndLine
	if end <= start {
		end = start + 1
	}
	if end-start > maxLines {
		end = start + maxLines
	}
	if end > len(lines) {
		end = len(lines)
	}
	out := strings.Join(lines[start:end], "\n")
	if fn.EndLine-start > maxLines {
		out += fmt.Sprintf("\n  ... (%d more lines)", fn.EndLine-end)
	}
	return out
}
